#[allow(unused_imports)]
use magnus::TryConvert as _;
#[allow(unused_imports)]
use magnus::value::InnerValue as _;
type RbParserHostBridgeRuntimeJob = Box<dyn FnOnce(&magnus::Ruby, magnus::Value) + Send + 'static>;

#[derive(Clone)]
struct RbParserHostBridgeRuntimeDispatcher {
    sender: std::sync::mpsc::SyncSender<RbParserHostBridgeRuntimeJob>,
}

impl RbParserHostBridgeRuntimeDispatcher {
    const QUEUE_CAPACITY: usize = 64;

    fn new(ruby: &magnus::Ruby, rb_obj: magnus::Value) -> Result<Self, magnus::Error> {
        use magnus::value::InnerValue as _;

        let (sender, receiver) = std::sync::mpsc::sync_channel(Self::QUEUE_CAPACITY);
        let inner = magnus::value::Opaque::from(rb_obj);
        let thread = ruby.thread_create_from_fn(move |ruby| {
            while let Ok(job) = Self::recv_without_gvl(&receiver) {
                let value = inner.get_inner_with(ruby);
                let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    job(ruby, value);
                }));
            }
        });

        // The active Ruby thread is VM-rooted; its ivar keeps the host object live
        // until every bridge sender is gone and the dispatcher exits.
        use magnus::Object as _;
        thread.ivar_set("__alef_trait_bridge_host", rb_obj)?;
        Ok(Self { sender })
    }

    fn dispatch<T, F>(&self, callback: F) -> Result<T, String>
    where
        T: Send + 'static,
        F: FnOnce(&magnus::Ruby, magnus::Value) -> T + Send + 'static,
    {
        let (result_sender, result_receiver) = std::sync::mpsc::sync_channel(1);
        self.sender
            .send(Box::new(move |ruby, value| {
                let result = callback(ruby, value);
                let _ = result_sender.send(result);
            }))
            .map_err(|_| "Ruby runtime dispatcher is not available".to_string())?;
        result_receiver
            .recv()
            .map_err(|_| "Ruby runtime dispatcher callback did not return".to_string())
    }

    fn recv_without_gvl(
        receiver: &std::sync::mpsc::Receiver<RbParserHostBridgeRuntimeJob>,
    ) -> Result<RbParserHostBridgeRuntimeJob, std::sync::mpsc::RecvError> {
        struct ReceiveState<'a> {
            receiver: &'a std::sync::mpsc::Receiver<RbParserHostBridgeRuntimeJob>,
            result: Option<Result<RbParserHostBridgeRuntimeJob, std::sync::mpsc::RecvError>>,
        }

        unsafe extern "C" fn receive(data: *mut std::ffi::c_void) -> *mut std::ffi::c_void {
            // SAFETY: the state pointer remains valid until Ruby returns from the
            // without-GVL callback on this same Ruby-created thread.
            let state = unsafe { &mut *(data as *mut ReceiveState<'_>) };
            state.result = Some(state.receiver.recv());
            std::ptr::null_mut()
        }

        let mut state = ReceiveState { receiver, result: None };
        // SAFETY: this runs on the dedicated Ruby-created dispatcher thread. The
        // callback touches only Rust channel state and the sender disconnect wakes it.
        unsafe {
            rb_sys::rb_thread_call_without_gvl(
                Some(receive),
                &mut state as *mut ReceiveState<'_> as *mut std::ffi::c_void,
                None,
                std::ptr::null_mut(),
            );
        }
        state.result.unwrap_or_else(|| Err(std::sync::mpsc::RecvError))
    }
}

/// Wrapper that bridges a foreign Rb object to the `ParserHost` trait.
pub struct RbParserHostBridge {
    inner: magnus::value::Opaque<magnus::Value>,
    cached_name: String,
    runtime_dispatcher: RbParserHostBridgeRuntimeDispatcher,
}

impl std::fmt::Debug for RbParserHostBridge {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "RbParserHostBridge")
    }
}

impl RbParserHostBridge {
    /// Create a new bridge wrapping a Ruby object.
    /// Validates that the Ruby object responds to all required methods.
    pub fn new(rb_obj: magnus::Value, name: String) -> Result<Self, magnus::Error> {
        // SAFETY: constructors are called by generated Magnus registration functions.
        let ruby = unsafe { magnus::Ruby::get_unchecked() };
        if !rb_obj.respond_to("descriptor", false).unwrap_or(false) {
            let ruby = unsafe { magnus::Ruby::get_unchecked() };
            return Err(magnus::Error::new(
                ruby.exception_runtime_error(),
                format!("Ruby object missing required method: {}", "descriptor"),
            ));
        }
        if !rb_obj.respond_to("probe_batch", false).unwrap_or(false) {
            let ruby = unsafe { magnus::Ruby::get_unchecked() };
            return Err(magnus::Error::new(
                ruby.exception_runtime_error(),
                format!("Ruby object missing required method: {}", "probe_batch"),
            ));
        }
        if !rb_obj.respond_to("parse_batch", false).unwrap_or(false) {
            let ruby = unsafe { magnus::Ruby::get_unchecked() };
            return Err(magnus::Error::new(
                ruby.exception_runtime_error(),
                format!("Ruby object missing required method: {}", "parse_batch"),
            ));
        }
        let runtime_dispatcher = RbParserHostBridgeRuntimeDispatcher::new(&ruby, rb_obj)?;

        Ok(Self {
            inner: magnus::value::Opaque::from(rb_obj),
            cached_name: name,
            runtime_dispatcher,
        })
    }
}

impl structuredmerge_core::ParserHost for RbParserHostBridge {
    fn descriptor(
        &self,
    ) -> std::result::Result<
        structuredmerge_core::service::ParserProviderDescriptor,
        structuredmerge_core::CoreError,
    > {
        let callback = move |ruby: &magnus::Ruby,
                             value: magnus::Value|
              -> std::result::Result<
            structuredmerge_core::service::ParserProviderDescriptor,
            structuredmerge_core::CoreError,
        > {
            let val: magnus::Value = match value.funcall::<_, _, magnus::Value>("descriptor", ()) {
                Ok(v) => v,
                Err(e) => {
                    return Err(structuredmerge_core::CoreError::new(format!(
                        "Ruby method 'descriptor' failed: {}",
                        e
                    )));
                }
            }; // Native-object return: the binding struct's `TryConvert` accepts the host's native wrapped
            // object (and still a Hash/JSON via `to_json`); `From<ParserProviderDescriptor>` yields core.
            <ParserProviderDescriptor as magnus::TryConvert>::try_convert(val)
                .map(Into::into)
                .map_err(|e| {
                    structuredmerge_core::CoreError::new(format!(
                        "Failed to convert Ruby 'descriptor' return value: {}",
                        e
                    ))
                })
        };
        match magnus::Ruby::get() {
            Ok(ruby) => callback(&ruby, self.inner.get_inner_with(&ruby)),
            Err(_) => match self.runtime_dispatcher.dispatch(callback) {
                Ok(result) => result,
                Err(error) => Err(structuredmerge_core::CoreError::new(format!(
                    "Ruby runtime dispatcher failed for method 'descriptor': {}",
                    error
                ))),
            },
        }
    }

    fn probe_batch(
        &self,
        request: structuredmerge_core::ProbeBatchRequest,
    ) -> std::result::Result<structuredmerge_core::ProbeBatchResult, structuredmerge_core::CoreError>
    {
        let request = request;
        let callback = move |ruby: &magnus::Ruby,
                             value: magnus::Value|
              -> std::result::Result<
            structuredmerge_core::ProbeBatchResult,
            structuredmerge_core::CoreError,
        > {
            let val: magnus::Value = match value.funcall::<_, _, magnus::Value>(
                "probe_batch",
                ({
                    use magnus::IntoValue;
                    ProbeBatchRequest::from(request.clone()).into_value_with(&ruby)
                },),
            ) {
                Ok(v) => v,
                Err(e) => {
                    return Err(structuredmerge_core::CoreError::new(format!(
                        "Ruby method 'probe_batch' failed: {}",
                        e
                    )));
                }
            }; // Native-object return: the binding struct's `TryConvert` accepts the host's native wrapped
            // object (and still a Hash/JSON via `to_json`); `From<ProbeBatchResult>` yields core.
            <ProbeBatchResult as magnus::TryConvert>::try_convert(val).map(Into::into).map_err(
                |e| {
                    structuredmerge_core::CoreError::new(format!(
                        "Failed to convert Ruby 'probe_batch' return value: {}",
                        e
                    ))
                },
            )
        };
        match magnus::Ruby::get() {
            Ok(ruby) => callback(&ruby, self.inner.get_inner_with(&ruby)),
            Err(_) => match self.runtime_dispatcher.dispatch(callback) {
                Ok(result) => result,
                Err(error) => Err(structuredmerge_core::CoreError::new(format!(
                    "Ruby runtime dispatcher failed for method 'probe_batch': {}",
                    error
                ))),
            },
        }
    }

    fn parse_batch(
        &self,
        request: structuredmerge_core::ParseBatchRequest,
    ) -> std::result::Result<structuredmerge_core::ParseBatchResult, structuredmerge_core::CoreError>
    {
        let request = request;
        let callback = move |ruby: &magnus::Ruby,
                             value: magnus::Value|
              -> std::result::Result<
            structuredmerge_core::ParseBatchResult,
            structuredmerge_core::CoreError,
        > {
            let val: magnus::Value = match value.funcall::<_, _, magnus::Value>(
                "parse_batch",
                ({
                    use magnus::IntoValue;
                    ParseBatchRequest::from(request.clone()).into_value_with(&ruby)
                },),
            ) {
                Ok(v) => v,
                Err(e) => {
                    return Err(structuredmerge_core::CoreError::new(format!(
                        "Ruby method 'parse_batch' failed: {}",
                        e
                    )));
                }
            }; // Native-object return: the binding struct's `TryConvert` accepts the host's native wrapped
            // object (and still a Hash/JSON via `to_json`); `From<ParseBatchResult>` yields core.
            <ParseBatchResult as magnus::TryConvert>::try_convert(val).map(Into::into).map_err(
                |e| {
                    structuredmerge_core::CoreError::new(format!(
                        "Failed to convert Ruby 'parse_batch' return value: {}",
                        e
                    ))
                },
            )
        };
        match magnus::Ruby::get() {
            Ok(ruby) => callback(&ruby, self.inner.get_inner_with(&ruby)),
            Err(_) => match self.runtime_dispatcher.dispatch(callback) {
                Ok(result) => result,
                Err(error) => Err(structuredmerge_core::CoreError::new(format!(
                    "Ruby runtime dispatcher failed for method 'parse_batch': {}",
                    error
                ))),
            },
        }
    }
}

